		changed: snapshot.entries.filter((e) => !e.untracked && !e.conflict).length,
		untracked: snapshot.entries.filter((e) => e.untracked).length,
	};
}

function headerRow(repo: Extract<RepoStatus, { git: true }>): TspNode {
	const { snapshot } = repo;
