export const canonicalSwarmSystemPrompt = swarmForgeSystemPrompt;

/** A named system prompt shown by the /sp picker. */
export interface SystemPromptPreset {
  name: string;
  content: string;
}

export interface PromptStore {
  prompts: SystemPromptPreset[];
  active?: string;
